/// <summary>Provides web search and page fetching capabilities.</summary>
sealed partial class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0 (compatible)" },
            { "Accept", "text/html,application/xhtml+xml" },
        },
    };

    [Description("Search the web for a query. Returns results as JSON with title, url, and snippet fields.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🌐 Searching: {query}");
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";

            var request = new HttpRequestMessage(HttpMethod.Get, url);
            var response = await Http.SendAsync(request);
            response.EnsureSuccessStatusCode();
            var html = await response.Content.ReadAsStringAsync();

            var results = ParseSearchResults(html);
            if (results.Count == 0)
                return "No results found.";

            return JsonSerializer.Serialize(results, JsonOptions);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Fetch the text content of a web page. Returns the readable text (truncated to ~6000 chars).")]
    public async Task<string> FetchPage(
        [Description("The full URL of the page to fetch")] string url)
    {
        Console.WriteLine($"  📄 Fetching: {url}");
        try
        {
            var html = await Http.GetStringAsync(url);
            var text = ExtractReadableText(html);

            const int maxLen = 6000;
            if (text.Length > maxLen)
                text = text[..maxLen] + "\n\n[…truncated]";

            return text;
        }
        catch (Exception ex)
        {
            return $"Fetch failed: {ex.Message}";
        }
    }

    // ── HTML parsing helpers ───────────────────────────────────────────────────

    private static List<SearchResult> ParseSearchResults(string html)
    {
        var results = new List<SearchResult>();

        // DuckDuckGo result links have class "result__a"
        foreach (Match m in ResultLinkRegex().Matches(html))
        {
            var href = WebUtility.HtmlDecode(m.Groups["url"].Value);
            var title = StripHtml(m.Groups["title"].Value);

            // DuckDuckGo wraps the real URL in a redirect; extract it.
            if (href.Contains("uddg="))
            {
                var uddg = Regex.Match(href, @"uddg=([^&]+)");
                if (uddg.Success)
                    href = WebUtility.UrlDecode(uddg.Groups[1].Value);
            }

            if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(href))
                continue;

            // Find the snippet associated with this result
            var snippet = "";
            var snippetMatch = ResultSnippetRegex().Match(html, m.Index);
            if (snippetMatch.Success)
                snippet = StripHtml(snippetMatch.Groups["text"].Value).Trim();

            results.Add(new SearchResult(title.Trim(), href.Trim(), snippet));
            if (results.Count >= 8) break;
        }

        return results;
    }

    private static string ExtractReadableText(string html)
    {
        // Remove script/style blocks
        var cleaned = ScriptStyleRegex().Replace(html, " ");
        // Convert block tags to newlines
        cleaned = BlockTagRegex().Replace(cleaned, "\n");
        // Strip remaining tags
        cleaned = TagRegex().Replace(cleaned, " ");
        // Decode entities
        cleaned = WebUtility.HtmlDecode(cleaned);
        // Collapse whitespace
        cleaned = ExcessWhitespaceRegex().Replace(cleaned, " ");
        // Collapse blank lines
        cleaned = BlankLinesRegex().Replace(cleaned, "\n\n");

        return cleaned.Trim();
    }

    private static string StripHtml(string s) =>
        WebUtility.HtmlDecode(TagRegex().Replace(s, "")).Trim();

    [GeneratedRegex("""<a[^>]+class="[^"]*result__a[^"]*"[^>]*href="(?<url>[^"]+)"[^>]*>(?<text>(?<title>.*?))</a>""",
        RegexOptions.Singleline | RegexOptions.IgnoreCase)]
    private static partial Regex ResultLinkRegex();

    [GeneratedRegex("""<a[^>]+class="[^"]*result__snippet[^"]*"[^>]*>(?<text>.*?)</a>""",
        RegexOptions.Singleline | RegexOptions.IgnoreCase)]
    private static partial Regex ResultSnippetRegex();

    [GeneratedRegex("""<(script|style)[^>]*>.*?</\1>""", RegexOptions.Singleline | RegexOptions.IgnoreCase)]
    private static partial Regex ScriptStyleRegex();

    [GeneratedRegex("""</(p|div|h[1-6]|li|tr|br|hr)\b[^>]*>""", RegexOptions.IgnoreCase)]
    private static partial Regex BlockTagRegex();

    [GeneratedRegex("<[^>]+>")]
    private static partial Regex TagRegex();

    [GeneratedRegex(@"[^\S\n]+")]
    private static partial Regex ExcessWhitespaceRegex();

    [GeneratedRegex(@"\n{3,}")]
    private static partial Regex BlankLinesRegex();

    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = false };

    private record SearchResult(string Title, string Url, string Snippet);
}

/// <summary>In-memory note-taking tool the agent uses to track findings.</summary>
sealed class NotesTool
{
    private readonly List<Note> _notes = [];

    [Description("Save a research note. Use this to record important findings as you discover them.")]
    public string AddNote(
        [Description("Short label or category for the note")] string title,
        [Description("The content of the note")] string content)
    {
        _notes.Add(new Note(title, content, DateTime.UtcNow));
        Console.WriteLine($"  📝 Note saved: {title}");
        return $"Note #{_notes.Count} saved: {title}";
    }

    [Description("Retrieve all notes saved so far. Use this before writing your final summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            var n = _notes[i];
            sb.AppendLine($"--- Note #{i + 1}: {n.Title} ---");
            sb.AppendLine(n.Content);
            sb.AppendLine();
        }

        Console.WriteLine($"  📋 Retrieved {_notes.Count} note(s)");
        return sb.ToString();
    }

    private record Note(string Title, string Content, DateTime SavedAt);
}

