var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// ── Chat client with automatic function-calling ────────────────────────────────

var notes = new NotesTool();
var search = new WebSearchTool();

AIFunction[] tools =
[
    AIFunctionFactory.Create(search.SearchWeb),
    AIFunctionFactory.Create(search.FetchPage),
    AIFunctionFactory.Create(notes.AddNote),
    AIFunctionFactory.Create(notes.GetNotes),
];

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// ── Prompt for a topic ─────────────────────────────────────────────────────────

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// ── Run the agent ──────────────────────────────────────────────────────────────

List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research agent. Given a topic you must:
        1. Search the web for relevant information (try 2-3 different queries).
        2. Fetch the most promising pages and read them.
        3. Use AddNote to record every important finding as you go.
        4. When you have gathered enough information, call GetNotes to review
           everything you saved, then write a well-structured summary for the user.

        Guidelines:
        - Be thorough: use multiple search queries to cover different angles.
        - Be selective: only fetch pages that look genuinely relevant.
        - Keep notes concise but informative.
        - Your final summary should synthesize the notes into a coherent report
          with sections, key facts, and references where possible.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
];

var options = new ChatOptions
{
    Tools = [.. tools],
    Temperature = 0.2f,
};

// FunctionInvocationMiddleware handles the tool-call loop automatically.
