        try
        {
            var html = await Http.GetStringAsync(url);
            var text = ExtractReadableText(html);

            const int maxLen = 6000;
            if (text.Length > maxLen)
                text = text[..maxLen] + "\n\n[…truncated]";

            return text;
        }
        catch (Exception ex)
        {
            return $"Fetch failed: {ex.Message}";
        }
    }

