+/// <summary>In-memory note-taking tool the agent uses to track findings.</summary>
+sealed class NotesTool
+{
+    private readonly List<Note> _notes = [];
+
+    [Description("Save a research note. Use this to record important findings as you discover them.")]
+    public string AddNote(
+        [Description("Short label or category for the note")] string title,
+        [Description("The content of the note")] string content)
+    {
+        _notes.Add(new Note(title, content, DateTime.UtcNow));
+        Console.WriteLine($"  📝 Note saved: {title}");
+        return $"Note #{_notes.Count} saved: {title}";
+    }
+
+    [Description("Retrieve all notes saved so far. Use this before writing your final summary.")]
+    public string GetNotes()
+    {
+        if (_notes.Count == 0)
+            return "No notes have been saved yet.";
+
+        var sb = new StringBuilder();
+        for (var i = 0; i < _notes.Count; i++)
+        {
+            var n = _notes[i];
+            sb.AppendLine($"--- Note #{i + 1}: {n.Title} ---");
+            sb.AppendLine(n.Content);
+            sb.AppendLine();
+        }
+
+        Console.WriteLine($"  📋 Retrieved {_notes.Count} note(s)");
+        return sb.ToString();
+    }
+
+    private record Note(string Title, string Content, DateTime SavedAt);
